insert into public.prova_drafts(id,family_id,content) values('00000000-0000-4000-8000-000000004501','00000000-0000-4000-8000-000000003611',
'{"childId":"00000000-0000-4000-8000-000000003621","grade":5,"title":"Tekrar","purpose":"practice","format":"practice","subjects":["Matematik"],"topics":[],"target":2,"minutes":null,"difficulty":"orta","kind":"mixed","note":"","step":2,"blocks":[]}');
create function pg_temp.candidates() returns jsonb language sql as $$select public.get_repeat_candidates('00000000-0000-4000-8000-000000004501')$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003601","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003611","role":"parent"}}',true);
select is(jsonb_array_length(pg_temp.candidates()),2,'only wrong MC and parent-reviewed partial open answer');
select ok(pg_temp.candidates()::text like '%000000003702%','wrong choice included');
select ok(pg_temp.candidates()::text like '%000000003704%','parent partial included');
select ok(pg_temp.candidates()::text not like '%000000003703%','AI-only assessment not treated as reviewed');
select ok(pg_temp.candidates()::text not like '%000000003701%','latest correct supersedes old wrong');
select ok(pg_temp.candidates()::text not like '%Expected%','candidate does not include answer key');
select is((select version from public.prova_drafts where id='00000000-0000-4000-8000-000000004501'),1,'reading suggestions does not mutate draft');
select throws_ok($$select public.get_repeat_candidates(gen_random_uuid())$$,'42501','forbidden','unknown draft not disclosed');
reset role;
update public.prova_drafts set content=jsonb_set(content,'{subjects}','["Fen"]');
set local role authenticated;
select is(pg_temp.candidates(),'[]'::jsonb,'subject exact');
reset role;
update public.prova_drafts set content=jsonb_set(jsonb_set(content,'{subjects}','["Matematik"]'),'{grade}','6');
set local role authenticated;
select is(pg_temp.candidates(),'[]'::jsonb,'grade exact');
reset role;
update public.prova_drafts set content=jsonb_set(content,'{grade}','5');
update public.exam_answers set score=100 where question_id='00000000-0000-4000-8000-000000003704';
set local role authenticated;
select is(jsonb_array_length(pg_temp.candidates()),1,'review revision to correct removes suggestion');
reset role;
update public.exam_attempts set finished_at=now()-interval '91 days' where id='00000000-0000-4000-8000-000000003901';
set local role authenticated;
select is(jsonb_array_length(pg_temp.candidates()),1,'old assessments excluded, recent prior wrong may remain');
select ok(pg_temp.candidates()::text like '%000000003701%','only still-recent wrong observation remains');
reset role;
update public.prova_drafts set content=jsonb_set(content,'{childId}','null');
set local role authenticated;
select is(pg_temp.candidates(),'[]'::jsonb,'no child does not borrow another child results');
reset role;
update public.prova_drafts set submitted_at=now();
set local role authenticated;
select throws_ok($$select pg_temp.candidates()$$,'P0001','prova_draft_submitted','submitted draft cannot take suggestions');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003602","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003612","role":"parent"}}',true);
select throws_ok($$select pg_temp.candidates()$$,'42501','forbidden','other family cannot access known draft');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003601","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003611","role":"device","child_id":"00000000-0000-4000-8000-000000003621"}}',true);
select throws_ok($$select pg_temp.candidates()$$,'42501','forbidden','child cannot access parent suggestions');
reset role;
select ok(not has_function_privilege('anon','public.get_repeat_candidates(uuid)','EXECUTE'),'anonymous cannot read suggestions');

update public.app_settings set value='true' where key='question_groups.enabled';
update public.prova_drafts set submitted_at=null, content=jsonb_set(content,'{childId}','"00000000-0000-4000-8000-000000003621"');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003601","role":"authenticated","gina":{"family_id":"00000000-0000-4000-8000-000000003611","role":"parent"}}',true);
select lives_ok($$select public.save_question_source_group('00000000-0000-4000-8000-000000004511','{"title":"Ortak bahçe","body":"Bahçe 8 metre ve 6 metre kenarlıdır.","grade":5,"subject":"Matematik"}','[{"topic":"Çevre","kind":"open_ended","difficulty":"orta","stem":"Çevresi?","expected_answer":"28","solution":"2 × (8 + 6)"},{"topic":"Alan","kind":"open_ended","difficulty":"orta","stem":"Alanı?","expected_answer":"48","solution":"8 × 6"}]','[]')$$,'shared fixture saved through normal source contract');
reset role;
insert into public.exams(id,family_id,child_id,title,subject,grade,question_ids,status)
select '00000000-0000-4000-8000-000000004512','00000000-0000-4000-8000-000000003611','00000000-0000-4000-8000-000000003621','Ortak tekrar','Matematik',5,array_agg(question_id order by position),'assigned'
from public.question_source_members where group_id='00000000-0000-4000-8000-000000004511';
insert into public.exam_attempts(id,family_id,child_id,exam_id,status,finished_at) values('00000000-0000-4000-8000-000000004513','00000000-0000-4000-8000-000000003611','00000000-0000-4000-8000-000000003621','00000000-0000-4000-8000-000000004512','submitted',now());
insert into public.exam_answers(attempt_id,question_id,answer_text,score,graded_by)
select '00000000-0000-4000-8000-000000004513',question_id,'Çözümüm',case when position=1 then 50 else 100 end,'parent'
from public.question_source_members where group_id='00000000-0000-4000-8000-000000004511';
set local role authenticated;
select is((select count(*)::int from jsonb_array_elements(pg_temp.candidates()) v where v->>'kind'='group'),1,'one block for shared source');
select is((select (v->>'question_count')::int from jsonb_array_elements(pg_temp.candidates()) v where v->>'kind'='group'),2,'all source members retained including correct sibling');
select is((select (v->>'affected')::int from jsonb_array_elements(pg_temp.candidates()) v where v->>'kind'='group'),1,'reason count is not total group size');
reset role;
update public.exam_answers set score=0 where attempt_id='00000000-0000-4000-8000-000000004513';
set local role authenticated;
select is((select count(*)::int from jsonb_array_elements(pg_temp.candidates()) v where v->>'kind'='group'),1,'two wrong members still one group');
select is((select (v->>'affected')::int from jsonb_array_elements(pg_temp.candidates()) v where v->>'kind'='group'),2,'both reviewed members counted');
select lives_ok($$select public.save_prova_draft('00000000-0000-4000-8000-000000004514','00000000-0000-4000-8000-000000004501',1,
jsonb_set((select content from public.prova_drafts where id='00000000-0000-4000-8000-000000004501'),'{blocks}',(select jsonb_agg(jsonb_build_object('kind',v->>'kind','id',v->>'id','source','library')) from jsonb_array_elements(pg_temp.candidates()) v)))$$,'repeat blocks use existing versioned draft writer');
select is((select version from public.prova_drafts where id='00000000-0000-4000-8000-000000004501'),2,'single draft edit');
select is((select exam_id from public.prova_drafts where id='00000000-0000-4000-8000-000000004501'),null::uuid,'selection never assigns exam automatically');
reset role;
select * from finish();
rollback;
